with flattened_attrs as (select id, host, level, latency_ms, payload_json, context, context['trace'] as trace, coalesce(context['trace'], 'direct') as trace_or_default from app_logs where latency_ms >= 2359) select host, level, bit_and(latency_ms) as latency_ms_bit_and, count(case when host = 'h1' then 1 end) as h1_count, count_if(host = 'h2') as h2_events, bit_and(latency_ms) as latency_ms_bit_and_2, stddev_samp(latency_ms) as latency_ms_stddev from flattened_attrs group by 1, 2 order by h2_events nulls last;
